// Package gen writes code for a checked schema.
package gen

import (
	"bytes"
	"fmt"
	"sort"

	"github.com/wow-look-at-my/go-ipc/ipcgen/internal/schema"
)

// Header is the first line of every generated file, without its comment marker.
const Header = "Code generated by ipcgen. DO NOT EDIT."

var generators = map[string]func(*schema.Schema) ([]byte, error){
	"go":   genGo,
	"c":    genC,
	"cpp":  genCpp,
	"py":   genPy,
	"json": genJSON,
}

// Languages returns the names that Generate accepts, sorted.
func Languages() []string {
	var out []string
	for k := range generators {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// Generate returns the code for s in lang.
func Generate(lang string, s *schema.Schema) ([]byte, error) {
	g := generators[lang]
	if g == nil {
		return nil, fmt.Errorf("unknown language %q, want one of %v", lang, Languages())
	}
	return g(s)
}

// writer collects lines of output.
type writer struct {
	bytes.Buffer
}

// line writes one formatted line. A line with no arguments is written as it is.
func (w *writer) line(format string, args ...any) {
	if len(args) == 0 {
		w.WriteString(format)
	} else {
		fmt.Fprintf(w, format, args...)
	}
	w.WriteByte('\n')
}
